NEW = {'app/auth.py': '"""Login for Krishi: scrypt password hashes, HMAC-signed session tokens, and FastAPI dependencies\nthat enforce roles (farmer / buyer / admin) and ownership. Standard library only."""\nimport base64, hashlib, hmac, json, os, secrets, time\nfrom fastapi import Depends, Header, HTTPException, Query\nfrom .db import conn\n\n# Set KS_SECRET in .env so sessions survive a restart. Without it a random key is made per process.\nSECRET = (os.getenv("KS_SECRET") or secrets.token_hex(32)).encode()\nTTL = int(os.getenv("KS_TOKEN_HOURS", "12")) * 3600\n_DUMMY = None\n\n\ndef hash_password(pw: str) -> str:\n    salt = secrets.token_bytes(16)\n    h = hashlib.scrypt(pw.encode(), salt=salt, n=2 ** 14, r=8, p=1, dklen=32)\n    return f"scrypt${salt.hex()}${h.hex()}"\n\n\ndef check_password(pw: str, stored: str) -> bool:\n    try:\n        _, salt, h = stored.split("$")\n        calc = hashlib.scrypt(pw.encode(), salt=bytes.fromhex(salt), n=2 ** 14, r=8, p=1, dklen=32)\n        return hmac.compare_digest(calc.hex(), h)\n    except Exception:\n        return False\n\n\ndef burn_time(pw: str):\n    """Spend the same time as a real check, so an unknown phone number is not faster to reject."""\n    global _DUMMY\n    if _DUMMY is None:\n        _DUMMY = hash_password("not-a-real-password")\n    check_password(pw, _DUMMY)\n\n\ndef _b64(b: bytes) -> str:\n    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()\n\n\ndef _unb64(s: str) -> bytes:\n    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))\n\n\ndef make_token(uid: int, role: str) -> str:\n    body = _b64(json.dumps({"id": uid, "role": role, "exp": int(time.time()) + TTL}).encode())\n    return body + "." + _b64(hmac.new(SECRET, body.encode(), hashlib.sha256).digest())\n\n\ndef read_token(tok: str):\n    try:\n        body, sig = tok.split(".")\n        good = _b64(hmac.new(SECRET, body.encode(), hashlib.sha256).digest())\n        if not hmac.compare_digest(sig, good):\n            return None\n        d = json.loads(_unb64(body))\n        return d if d["exp"] >= time.time() else None\n    except Exception:\n        return None\n\n\ndef ensure_admin():\n    """Create or refresh the admin account from KS_ADMIN_USER (default \'admin\') and KS_ADMIN_PASSWORD.\n    Admin logs in with that username in the phone field. With no password set, there is no admin."""\n    pw = os.getenv("KS_ADMIN_PASSWORD", "")\n    if not pw:\n        return False\n    user = os.getenv("KS_ADMIN_USER", "admin")\n    with conn() as c:\n        r = c.execute("SELECT id, password_hash FROM users WHERE role=\'admin\' AND phone=?", (user,)).fetchone()\n        if r and r["password_hash"] and check_password(pw, r["password_hash"]):\n            return True\n        h = hash_password(pw)\n        if r:\n            c.execute("UPDATE users SET password_hash=? WHERE id=?", (h, r["id"]))\n        else:\n            c.execute("INSERT INTO users(name,role,loc,phone,password_hash) VALUES(\'Admin\',\'admin\',\'\',?,?)", (user, h))\n    return True\n\n\ndef _user_from(tok: str):\n    d = read_token(tok) if tok else None\n    if not d:\n        raise HTTPException(401, "Please log in")\n    with conn() as c:\n        r = c.execute("SELECT id, name, role FROM users WHERE id=?", (d["id"],)).fetchone()\n    if not r or r["role"] != d["role"]:\n        raise HTTPException(401, "Please log in")\n    return {"id": r["id"], "name": r["name"], "role": r["role"]}\n\n\ndef _bearer(h: str) -> str:\n    return h[7:].strip() if h.lower().startswith("bearer ") else ""\n\n\ndef current_user(authorization: str = Header(default="")):\n    return _user_from(_bearer(authorization))\n\n\ndef current_user_q(authorization: str = Header(default=""), t: str = Query(default="")):\n    """Same as current_user, but also accepts ?t=<token> because <img> and <video> tags cannot send headers."""\n    return _user_from(_bearer(authorization) or t)\n\n\ndef admin_only(user=Depends(current_user)):\n    if user["role"] != "admin":\n        raise HTTPException(403, "Admin only")\n    return user\n\n\ndef role(*roles):\n    def dep(user=Depends(current_user)):\n        if user["role"] not in roles:\n            raise HTTPException(403, "Not allowed for your role")\n        return user\n    return dep\n\n\ndef _parties(oid: int):\n    with conn() as c:\n        r = c.execute("SELECT o.buyer_id, o.state, l.farmer_id FROM orders o JOIN listings l ON l.id=o.listing_id WHERE o.id=?", (oid,)).fetchone()\n    if not r:\n        raise HTTPException(404, "order not found")\n    return r\n\n\ndef order_party(oid: int, user=Depends(current_user)):\n    if user["role"] == "admin":\n        return user\n    r = _parties(oid)\n    if user["id"] not in (r["buyer_id"], r["farmer_id"]):\n        raise HTTPException(403, "Not your order")\n    return user\n\n\n# Who may trigger each order action (admin may do all). Mirrors PERM in frontend/index.html.\nORDER_ACTIONS = {"fund": {"buyer"}, "harvest": {"farmer"}, "ship": {"farmer"}, "deliver": {"buyer"},\n                 "release": {"buyer"}, "dispute": {"buyer", "farmer"}, "refund": {"farmer"},\n                 "cancel": {"buyer", "farmer"}, "undo": {"buyer", "farmer"}, "buyer_cancel": {"buyer"}}\n\n\ndef authorize_order(user, oid: int, action: str):\n    if user["role"] == "admin":\n        return\n    r = _parties(oid)\n    rel = "buyer" if user["id"] == r["buyer_id"] else ("farmer" if user["id"] == r["farmer_id"] else None)\n    if rel is None or rel not in ORDER_ACTIONS[action]:\n        raise HTTPException(403, "You cannot do this on this order")\n    if r["state"] == "DISPUTED" and action in ("release", "refund"):\n        raise HTTPException(403, "A disputed order can only be settled by the admin")\n\n\ndef ticket_owner(tid: int, user=Depends(current_user)):\n    if user["role"] == "admin":\n        return user\n    with conn() as c:\n        r = c.execute("SELECT farmer_id FROM tickets WHERE id=?", (tid,)).fetchone()\n    if not r:\n        raise HTTPException(404, "ticket not found")\n    if r["farmer_id"] != user["id"]:\n        raise HTTPException(403, "Not your ticket")\n    return user\n\n\ndef media_access(mid: int, user=Depends(current_user_q)):\n    if user["role"] == "admin":\n        return user\n    with conn() as c:\n        r = c.execute("SELECT t.farmer_id FROM ticket_media m JOIN tickets t ON t.id=m.ticket_id WHERE m.id=?", (mid,)).fetchone()\n    if not r:\n        raise HTTPException(404, "not found")\n    if r["farmer_id"] != user["id"]:\n        raise HTTPException(403, "Not your file")\n    return user\n\n\ndef self_buyer(buyer_id: int, user=Depends(current_user)):\n    if user["role"] == "admin" or (user["role"] == "buyer" and user["id"] == buyer_id):\n        return user\n    raise HTTPException(403, "Not your account")\n', 'app/__init__.py': 'import os\n\n\ndef _load_env(path=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".env")):\n    """Tiny .env reader (KEY=VALUE lines). Real environment variables win. Values are never printed."""\n    try:\n        with open(path, encoding="utf-8") as f:\n            for line in f:\n                line = line.strip()\n                if not line or line.startswith("#") or "=" not in line:\n                    continue\n                k, v = line.split("=", 1)\n                os.environ.setdefault(k.strip(), v.strip().strip(\'"\').strip("\'"))\n    except OSError:\n        pass\n\n\n_load_env()\n', 'tests/helpers.py': '"""Small helpers so tests can register people and call the API with a login token."""\nimport itertools\n_n = itertools.count(1)\nPW = "pass-12345"\nADMIN_PW = "test-admin-password"\n\n\ndef bearer(token):\n    return {"Authorization": "Bearer " + token}\n\n\ndef register(client, role, name=None, loc="Bangalore", buyer_type="Other"):\n    """Register a farmer or buyer; returns (user_id, auth_headers)."""\n    ph = "98765%05d" % next(_n)\n    body = {"name": name or f"{role}-{ph}", "role": role, "loc": loc, "phone": ph, "password": PW,\n            "buyer_type": buyer_type if role == "buyer" else ""}\n    r = client.post("/users", json=body)\n    assert r.status_code == 200, r.text\n    j = r.json()\n    return j["id"], bearer(j["token"])\n\n\ndef admin(client):\n    r = client.post("/login", json={"phone": "admin", "password": ADMIN_PW})\n    assert r.status_code == 200, r.text\n    return bearer(r.json()["token"])\n', 'tests/conftest.py': '"""Every test runs against its own temporary database. krishi.db is never touched."""\nimport os, tempfile\n_TMP = tempfile.mkdtemp(prefix="ks_tests_")\nos.environ["KS_DB"] = os.path.join(_TMP, "session.db")  # set before app.main is imported (it calls db.init() on import)\nos.environ["KS_SECRET"] = "test-secret-not-for-production"\nos.environ["KS_ADMIN_USER"] = "admin"\nos.environ["KS_ADMIN_PASSWORD"] = "test-admin-password"\nos.environ["KS_RATE_LIMIT"] = "1000000"  # the many HTTP tests must not trip the rate limiter\nos.environ.setdefault("KS_PRICES", os.path.join(os.path.dirname(__file__), "..", "data", "prices.csv"))\n\nimport pytest\nfrom app import db, escrow, cases, idempotency, imagecheck, auth\n\n\n@pytest.fixture(autouse=True)\ndef _fresh_db(tmp_path, monkeypatch):\n    monkeypatch.setattr(db, "DB", str(tmp_path / "test.db"))\n    monkeypatch.setattr(escrow, "FEE", 0.01)\n    monkeypatch.setattr(escrow, "BUYER_MARKUP", 0.05)\n    monkeypatch.setattr(escrow, "CANCEL_FEE", 0.10)\n    db.init()\n    with db.conn() as c:\n        cases.init(c); idempotency.init(c); imagecheck.init(c)\n    auth.ensure_admin()\n    yield\n', 'tests/test_phase1.py': '"""Phase 1 regression tests: double fee, route shadowing, oversell race, cancel stock restore."""\nimport json, threading, pytest\nfrom fastapi.testclient import TestClient\nfrom fastapi import HTTPException\nfrom app import main, escrow, pricing_rules\nfrom app.db import conn\nfrom tests.helpers import register, admin\n\nclient = TestClient(main.app)\n\n\ndef _mk(price, qty):\n    f, fh = register(client, "farmer")\n    b, bh = register(client, "buyer")\n    with conn() as c:\n        lid = c.execute("INSERT INTO listings(farmer_id,crop,qty,price,loc,status) VALUES(?,?,?,?,?,\'ACTIVE\')",\n                        (f, "Tomato", qty, price, "Bangalore")).lastrowid\n    return f, b, lid, fh, bh\n\n\ndef _step(oid, action, hdr):\n    r = client.post(f"/orders/{oid}/{action}", headers=hdr)\n    assert r.status_code == 200, (action, r.text)\n\n\ndef _release(oid, fh, bh):\n    _step(oid, "fund", bh); _step(oid, "harvest", fh); _step(oid, "ship", fh)\n    _step(oid, "deliver", bh); _step(oid, "release", bh)\n\n\ndef _released_detail(oid):\n    led = client.get(f"/orders/{oid}/ledger", headers=admin(client)).json()\n    return json.loads([x for x in led if x["event"] == "RELEASED"][0]["detail"])\n\n\n@pytest.mark.parametrize("price,qty,fee,mk", [(30, 200, 0.01, 0.05), (47.5, 123, 0.02, 0.05),\n                                              (12.34, 1000, 0.0, 0.03), (99.99, 57, 0.01, 0.10)])\ndef test_released_ledger_equals_quote(monkeypatch, price, qty, fee, mk):\n    monkeypatch.setattr(escrow, "FEE", fee); monkeypatch.setattr(escrow, "BUYER_MARKUP", mk)\n    f, b, lid, fh, bh = _mk(price, qty)\n    r = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": qty}, headers=bh)\n    assert r.status_code == 200, r.text\n    oid = r.json()["id"]\n    _release(oid, fh, bh)\n    q = pricing_rules.quote(price, qty, 1.0, farmer_fee_pct=fee * 100, buyer_fee_pct=mk * 100)\n    d = _released_detail(oid)\n    assert d["farmer_gets"] == q["farmer_payout"]\n    assert d["buyer_paid"] == q["buyer_pays"]\n    assert d["platform_total"] == q["platform_revenue"]\n    assert d["commission"] == round(q["gross"] - q["farmer_payout"], 2)\n    mine = [o for o in client.get("/orders", params={"view": "farmer"}, headers=fh).json() if o["id"] == oid][0]\n    assert mine["payout"] == q["farmer_payout"]\n    s = client.get("/admin/summary", headers=admin(client)).json()\n    assert s["platform_revenue"] == q["platform_revenue"]\n    assert s["farmer_payouts"] == q["farmer_payout"]\n\n\ndef test_fee_trace_price30_qty200():\n    f, b, lid, fh, bh = _mk(30, 200)\n    oid = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": 200}, headers=bh).json()["id"]\n    _release(oid, fh, bh)\n    d = _released_detail(oid)\n    assert (d["farmer_gets"], d["buyer_paid"], d["platform_total"]) == (5940.0, 6300.0, 360.0)\n\n\ndef test_admin_platform_revenue_is_sum_of_buyer_minus_amount():\n    for p, q in [(30, 200), (41.7, 90), (8.25, 410)]:\n        f, b, lid, fh, bh = _mk(p, q)\n        oid = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": q}, headers=bh).json()["id"]\n        _release(oid, fh, bh)\n    with conn() as c:\n        tot = c.execute("SELECT SUM(buyer_amount-amount) FROM orders WHERE state=\'RELEASED\'").fetchone()[0]\n    assert abs(client.get("/admin/summary", headers=admin(client)).json()["platform_revenue"] - tot) < 0.011\n\n\ndef test_dispute_case_reachable_over_http():\n    f, b, lid, fh, bh = _mk(30, 200)\n    oid = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": 200}, headers=bh).json()["id"]\n    r = client.post(f"/orders/{oid}/dispute_case", json={"text": "Tomatoes arrived rotten after 2 days of delivery"}, headers=bh)\n    assert r.status_code == 200, r.text\n    assert r.json()["status"] == "ESCALATE"\n    cid = r.json()["case_id"]\n    assert client.post(f"/cases/{cid}/resolve", json={"resolution": "Refund 50%"}, headers=admin(client)).status_code == 200\n    r2 = client.post(f"/orders/{oid}/dispute_case", json={"text": "tomato came rotten, delivery took 2 days"}, headers=bh)\n    assert r2.status_code == 200 and r2.json()["status"] == "AUTO"\n    assert client.post(f"/orders/{oid}/nonsense", headers=bh).status_code == 404  # generic route still works\n\n\ndef test_no_oversell_under_concurrency():\n    f, b, _, fh, bh = _mk(30, 1)\n    for rnd in range(5):\n        with conn() as c:\n            lids = [c.execute("INSERT INTO listings(farmer_id,crop,qty,price,loc,status) VALUES(?,?,1,30,\'Bangalore\',\'ACTIVE\')",\n                              (f, "Tomato")).lastrowid for _ in range(20)]\n        wins = []; barrier = threading.Barrier(8); lock = threading.Lock()\n\n        def worker():\n            for lid in lids:\n                barrier.wait()\n                try:\n                    main._place(main.Order(listing_id=lid, buyer_id=b, qty=1))\n                    with lock: wins.append(lid)\n                except HTTPException:\n                    pass\n        ts = [threading.Thread(target=worker) for _ in range(8)]\n        [t.start() for t in ts]; [t.join() for t in ts]\n        assert sorted(wins) == sorted(lids)  # exactly one order per lot\n        with conn() as c:\n            assert c.execute("SELECT COUNT(*) FROM listings WHERE qty<0").fetchone()[0] == 0\n            assert c.execute(f"SELECT COUNT(*) FROM orders WHERE listing_id IN ({\',\'.join(map(str, lids))})").fetchone()[0] == 20\n    assert escrow.verify_chain()[0]\n\n\ndef test_cancel_restores_stock_once():\n    f, b, lid, fh, bh = _mk(30, 10)\n    oid = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": 10}, headers=bh).json()["id"]\n    with conn() as c:\n        assert c.execute("SELECT qty FROM listings WHERE id=?", (lid,)).fetchone()[0] == 0\n    assert client.post(f"/orders/{oid}/buyer_cancel", headers=bh).status_code == 200\n    with conn() as c:\n        assert c.execute("SELECT qty FROM listings WHERE id=?", (lid,)).fetchone()[0] == 10\n    assert client.post(f"/orders/{oid}/buyer_cancel", headers=bh).status_code == 400  # second cancel: no double restore\n    with conn() as c:\n        assert c.execute("SELECT qty FROM listings WHERE id=?", (lid,)).fetchone()[0] == 10\n', 'tests/test_auth.py': '"""Phase 2: every protected route rejects missing and wrong-role tokens; owners only touch their own data."""\nimport pytest\nfrom fastapi.testclient import TestClient\nfrom app import main, auth\nfrom app.db import conn\nfrom tests.helpers import register, admin, bearer, PW\n\nclient = TestClient(main.app)\n\nADMIN_ONLY = [\n    ("get", "/admin/summary", None), ("get", "/admin/settings", None), ("post", "/admin/settings", {}),\n    ("get", "/cases", None), ("post", "/cases/1/resolve", {"resolution": "x"}), ("post", "/cases/1/wrong", None),\n    ("post", "/orders/1/fault/1", None), ("post", "/tickets/1/schedule?visit_date=2030-01-01", None),\n    ("post", "/tickets/1/reject", None), ("post", "/tickets/1/approve", {"grade": "A", "qty": 100, "price": 10, "agreed": True}),\n    ("post", "/listings/1/unpublish", None), ("get", "/tickets/1/photo_flags", None),\n]\nLOGIN_ONLY = [("get", "/me", None), ("get", "/users", None), ("get", "/orders", None), ("get", "/listings", None),\n              ("get", "/reliability/1", None), ("get", "/media/1", None), ("get", "/orders/1/ledger", None),\n              ("post", "/orders/1/fund", None), ("post", "/orders/1/dispute_case", {"text": "x"}),\n              ("get", "/subscription/1", None), ("post", "/subscribe/1/plus", None),\n              ("post", "/tickets/1/cancel", None), ("post", "/tickets/1/submit", None), ("delete", "/tickets/1", None)]\nROLE_ONLY = [("post", "/orders", {"listing_id": 1, "buyer_id": 1, "qty": 1}, "farmer"),\n             ("post", "/tickets", {"farmer_id": 1, "crop": "Tomato", "qty": 200, "location": "x", "phone": "9876543210",\n                                   "pref_date": "2030-01-01", "pref_slot": "Morning (8-11 am)"}, "buyer"),\n             ("get", "/tickets", None, "buyer")]\n\n\ndef call(method, path, body, hdr=None):\n    return client.request(method.upper(), path, json=body, headers=hdr or {})\n\n\n@pytest.mark.parametrize("method,path,body", ADMIN_ONLY)\ndef test_admin_routes(method, path, body):\n    assert call(method, path, body).status_code == 401\n    assert call(method, path, body, register(client, "farmer")[1]).status_code == 403\n    assert call(method, path, body, register(client, "buyer")[1]).status_code == 403\n    assert call(method, path, body, admin(client)).status_code not in (401, 403)\n\n\n@pytest.mark.parametrize("method,path,body", LOGIN_ONLY)\ndef test_login_required(method, path, body):\n    assert call(method, path, body).status_code == 401\n\n\n@pytest.mark.parametrize("method,path,body,bad_role", ROLE_ONLY)\ndef test_wrong_role_blocked(method, path, body, bad_role):\n    assert call(method, path, body).status_code == 401\n    assert call(method, path, body, register(client, bad_role)[1]).status_code == 403\n\n\ndef test_public_routes_need_no_login():\n    for p in ("/meta", "/ledger/verify", "/"):\n        assert client.get(p).status_code == 200, p\n\n\ndef test_register_login_me_and_rules():\n    uid, h = register(client, "farmer", name="Asha")\n    me = client.get("/me", headers=h).json()\n    assert me["id"] == uid and me["role"] == "farmer"\n    base = {"name": "A", "loc": "x", "phone": "9123456780", "password": PW, "buyer_type": ""}\n    assert client.post("/users", json={**base, "role": "admin"}).status_code == 400          # nobody registers as admin\n    assert client.post("/users", json={**base, "role": "farmer", "password": "short"}).status_code == 400\n    assert client.post("/users", json={**base, "role": "farmer", "phone": ""}).status_code == 400\n    assert client.post("/users", json={**base, "role": "farmer"}).status_code == 200\n    assert client.post("/users", json={**base, "role": "farmer"}).status_code == 409         # phone already used\n    assert client.post("/login", json={"phone": "9123456780", "password": PW}).status_code == 200\n    assert client.post("/login", json={"phone": "9123456780", "password": "wrong-password"}).status_code == 401\n    assert client.post("/login", json={"phone": "9000000000", "password": PW}).status_code == 401\n    with conn() as c:  # a password is never stored in clear text\n        assert c.execute("SELECT COUNT(*) FROM users WHERE password_hash=?", (PW,)).fetchone()[0] == 0\n        assert c.execute("SELECT password_hash FROM users WHERE id=?", (uid,)).fetchone()[0].startswith("scrypt$")\n    assert "password" not in str(client.get("/users", headers=admin(client)).json()).lower()\n\n\ndef test_tampered_and_expired_tokens(monkeypatch):\n    uid, h = register(client, "buyer")\n    tok = h["Authorization"][7:]\n    body, sig = tok.split(".")\n    assert client.get("/me", headers=bearer(body + "." + sig[:-2] + "AA")).status_code == 401\n    assert client.get("/me", headers={"Authorization": "Bearer garbage"}).status_code == 401\n    real = auth.time.time()\n    monkeypatch.setattr(auth.time, "time", lambda: real + auth.TTL + 10)\n    assert client.get("/me", headers=h).status_code == 401\n\n\ndef _order(price=30, qty=100):\n    f, fh = register(client, "farmer"); b, bh = register(client, "buyer")\n    with conn() as c:\n        lid = c.execute("INSERT INTO listings(farmer_id,crop,qty,price,loc,status) VALUES(?,?,?,?,?,\'ACTIVE\')", (f, "Tomato", qty, price, "Bangalore")).lastrowid\n    oid = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": qty}, headers=bh).json()["id"]\n    return f, fh, b, bh, oid\n\n\ndef test_order_ownership():\n    f, fh, b, bh, oid = _order()\n    _, other_b = register(client, "buyer"); _, other_f = register(client, "farmer")\n    assert client.post(f"/orders/{oid}/fund", headers=other_b).status_code == 403\n    assert client.post(f"/orders/{oid}/fund", headers=fh).status_code == 403           # farmer cannot fund\n    assert client.post(f"/orders/{oid}/fund", headers=bh).status_code == 200\n    assert client.post(f"/orders/{oid}/harvest", headers=other_f).status_code == 403\n    assert client.post(f"/orders/{oid}/harvest", headers=bh).status_code == 403        # buyer cannot harvest\n    assert client.post(f"/orders/{oid}/harvest", headers=fh).status_code == 200\n    assert client.post(f"/orders/{oid}/buyer_cancel", headers=other_b).status_code == 403\n    assert client.post(f"/orders/{oid}/dispute_case", json={"text": "x"}, headers=other_b).status_code == 403\n    assert client.get(f"/orders/{oid}/ledger", headers=other_b).status_code == 403\n    assert client.post(f"/orders/{oid}/dispute", headers=bh).status_code == 200\n    assert client.post(f"/orders/{oid}/release", headers=bh).status_code == 403       # disputed: admin only\n    assert client.post(f"/orders/{oid}/refund", headers=fh).status_code == 403\n    assert client.post(f"/orders/{oid}/refund", headers=admin(client)).status_code == 200\n\n\ndef test_order_lists_are_private_and_buyer_id_is_not_trusted():\n    f, fh, b, bh, oid = _order()\n    _, other_b = register(client, "buyer"); _, other_f = register(client, "farmer")\n    assert [o["id"] for o in client.get("/orders?view=buyer", headers=bh).json()] == [oid]\n    assert client.get("/orders?view=buyer", headers=other_b).json() == []\n    assert client.get("/orders?view=farmer", headers=other_f).json() == []\n    assert [o["id"] for o in client.get("/orders?view=admin", headers=fh).json()] == [oid]  # view is forced to the caller\'s role\n    assert [o["id"] for o in client.get("/orders", headers=admin(client)).json()] == [oid]\n    with conn() as c:\n        lid = c.execute("INSERT INTO listings(farmer_id,crop,qty,price,loc,status) VALUES(?,?,?,?,?,\'ACTIVE\')", (f, "Tomato", 100, 30, "Bangalore")).lastrowid\n    ob, obh = register(client, "buyer")\n    spoof = client.post("/orders", json={"listing_id": lid, "buyer_id": b, "qty": 100}, headers=obh).json()["id"]\n    with conn() as c:\n        assert c.execute("SELECT buyer_id FROM orders WHERE id=?", (spoof,)).fetchone()[0] == ob  # taken from the token\n\n\ndef test_ledger_detail_masked_for_non_admin():\n    f, fh, b, bh, oid = _order()\n    assert all(r["detail"] == "(admin only)" for r in client.get(f"/orders/{oid}/ledger?view=admin", headers=bh).json())\n    assert all(r["detail"] != "(admin only)" for r in client.get(f"/orders/{oid}/ledger", headers=admin(client)).json())\n\n\ndef test_users_listing_and_tickets_are_scoped():\n    fa, fha = register(client, "farmer"); fb, fhb = register(client, "farmer")\n    assert [u["id"] for u in client.get("/users", headers=fha).json()] == [fa]\n    assert {u["id"] for u in client.get("/users", headers=admin(client)).json()} >= {fa, fb}\n    t = client.post("/tickets", json={"farmer_id": fb, "crop": "Tomato", "qty": 200, "location": "x", "phone": "9876543210",\n                                      "pref_date": "2030-01-01", "pref_slot": "Morning (8-11 am)"}, headers=fha)\n    assert t.status_code == 200, t.text\n    tid = t.json()["id"]\n    with conn() as c:\n        assert c.execute("SELECT farmer_id FROM tickets WHERE id=?", (tid,)).fetchone()[0] == fa  # taken from the token\n    assert client.post(f"/tickets/{tid}/cancel", headers=fhb).status_code == 403\n    assert client.delete(f"/tickets/{tid}", headers=fhb).status_code == 403\n    assert client.post(f"/tickets/{tid}/submit", headers=fhb).status_code == 403\n    with conn() as c:\n        c.execute("UPDATE tickets SET status=\'OPEN\' WHERE id=?", (tid,))  # a draft cannot be cancelled, an open ticket can\n    assert client.post(f"/tickets/{tid}/cancel", headers=fha).status_code == 200\n\n\ndef test_media_needs_owner_or_admin(tmp_path):\n    fa, fha = register(client, "farmer"); fb, fhb = register(client, "farmer")\n    p = tmp_path / "x.jpg"; p.write_bytes(b"x")\n    with conn() as c:\n        tid = c.execute("INSERT INTO tickets(farmer_id,crop,qty,status) VALUES(?,?,?,?)", (fa, "Tomato", 200, "OPEN")).lastrowid\n        mid = c.execute("INSERT INTO ticket_media(ticket_id,kind,path,filename,size) VALUES(?,?,?,?,1)", (tid, "photo", str(p), "x.jpg")).lastrowid\n    assert client.get(f"/media/{mid}").status_code == 401\n    assert client.get(f"/media/{mid}", headers=fhb).status_code == 403\n    assert client.get(f"/media/{mid}", headers=fha).status_code == 200\n    tok = fha["Authorization"][7:]\n    assert client.get(f"/media/{mid}?t={tok}").status_code == 200  # <img src> cannot send headers, so ?t= works\n', 'tests/test_frontend_escape.py': '"""User-supplied text must be HTML-escaped before it is put into innerHTML."""\nimport json, pathlib, re, shutil, subprocess, pytest\nfrom fastapi.testclient import TestClient\nfrom app import main\nfrom tests.helpers import register, admin\n\nHTML = (pathlib.Path(__file__).parent.parent / "frontend" / "index.html").read_text(encoding="utf-8")\nFIELD = r"(?:name|loc|location|notes|reason|farmer|buyer|farmer_name|variety|crop|buyer_type)"\nREF = re.compile(r"(?<![\\w.$])([A-Za-z_]\\w*\\." + FIELD + r")\\b")\nEXPR = re.compile(r"\\$\\{([^{}`]*)\\}")\nPAYLOAD = "<img src=x onerror=alert(1)>"\n\n\ndef test_no_unescaped_user_fields_in_templates():\n    bad = [m.group(1) for m in EXPR.finditer(HTML)\n           if not any(k in m.group(1) for k in ("escH(", "esc(", "encodeURIComponent", "=>")) and REF.search(m.group(1))]\n    assert not bad, bad[:5]\n\n\n@pytest.mark.skipif(shutil.which("node") is None, reason="node is not installed")\ndef test_escape_helper_neutralises_payload():\n    line = re.search(r"const escH = .*", HTML).group(0)\n    out = subprocess.run(["node", "-e", line + "\\nconsole.log(escH(" + json.dumps(PAYLOAD) + "))"], capture_output=True, text=True).stdout.strip()\n    assert out == "&lt;img src=x onerror=alert(1)&gt;"\n\n\ndef test_hostile_name_is_stored_raw_and_served_raw():\n    client = TestClient(main.app)\n    uid, _ = register(client, "farmer", name=PAYLOAD)\n    names = [u["name"] for u in client.get("/users", headers=admin(client)).json()]\n    assert PAYLOAD in names  # stored and served raw; escaping happens only at render time\n'}
APPEND = {'README.md': ('## Login and roles', '\n\n## Login and roles\nThe API now needs a login. Farmers and buyers register with a 10-digit mobile number and a password (8 or more characters) and log in with the same number. Passwords are stored as scrypt hashes. Sessions are signed tokens that last 12 hours (`KS_TOKEN_HOURS`).\n\nPut these in `.env` (it is git-ignored; never commit it or paste it anywhere):\n\n    KS_SECRET=<a long random string>      # signs session tokens; without it a random one is made at every start\n    KS_ADMIN_USER=admin                   # admin logs in with this in the phone box\n    KS_ADMIN_PASSWORD=<choose a password>  # no password set means there is no admin account\n\nMake a secret with: `python -c "import secrets; print(secrets.token_hex(32))"`\n\nAdmin only: `/admin/*`, `/cases*`, fault marking, ticket approve/reject/schedule, unpublish, photo flags, and full ledger detail. Buyers and farmers can only act on their own orders and tickets.\n\nRate limiting note: the limiter keys on the connecting IP and ignores `X-Forwarded-For`. Behind a reverse proxy every user then shares one address. This is a known limit and is left as is for now.\n')}
FIELD = '(?:name|loc|location|notes|reason|farmer|buyer|farmer_name|variety|crop|buyer_type)'
REF = re.compile(r'(?<![\w.$])([A-Za-z_]\w*\.' + FIELD + r')\b')
EXPR = re.compile(r'\$\{([^{}`]*)\}')

def flex(old):
    return re.compile(r'\r?\n'.join(re.escape(p) for p in old.split('\n')))

def apply(text, pairs, path):
    for old, new, cnt in pairs:
        ms = list(flex(old).finditer(text))
        if len(ms) != cnt:
            sys.exit(f"STOPPED, nothing written: anchor found {len(ms)} times (expected {cnt}) in {path}: {old[:70]!r}")
        for m in reversed(ms):
            eol = '\r\n' if '\r\n' in m.group(0) else ('\r\n' if text.count('\r\n') > text.count('\n') / 2 else '\n')
            text = text[:m.start()] + new.replace('\n', eol) + text[m.end():]
    return text

def esc_templates(text):
    def fix(m):
        e = m.group(1)
        if 'escH(' in e or 'esc(' in e or 'encodeURIComponent' in e or '=>' in e:
            return m.group(0)
        return '${' + REF.sub(lambda r: 'escH(' + r.group(1) + ')', e) + '}'
    return EXPR.sub(fix, text)

def main():
    if not os.path.isfile('app/main.py') or not os.path.isfile('tests/test_phase1.py'):
        sys.exit("Run this from the repo root, after Phase 1 was applied.")
    if os.path.exists('app/auth.py'):
        sys.exit("app/auth.py already exists: Phase 2 looks already applied. Nothing written.")
    out = {}
    for path, pairs in PAIRS.items():
        text = open(path, newline='', encoding='utf-8').read()
        text = apply(text, pairs, path)
        if path == 'frontend/index.html':
            text = esc_templates(text)
        out[path] = text
    for path, (marker, add) in APPEND.items():
        text = open(path, newline='', encoding='utf-8').read()
        if marker not in text:
            eol = '\r\n' if '\r\n' in text else '\n'
            out[path] = text.rstrip() + eol + add.replace('\n', eol)
    for path, text in out.items():
        open(path, 'w', newline='', encoding='utf-8').write(text)
    for path, text in NEW.items():
        open(path, 'w', newline='', encoding='utf-8').write(text)
    print("OK. Changed:", ", ".join(list(out) + list(NEW)))

main()